import {roles, getDeck, sentenceLead} from './data.js?v=20261019-8';

const $=s=>document.querySelector(s), root=$('#display');
const room=new URLSearchParams(location.search).get('room')||'';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state=null, selected=null, autoOpen=true, largeText=false, loading=false, authenticated=false;
let signatures=new Map(), previousJSON='', connection='연결 중…';
const groupAt=i=>state?.groups.find(g=>g.id===String(i));
function signature(g){return JSON.stringify([g.submittedAt||0,g.board,g.reasons,g.reason]);}
function readyGroups(){return (state?.groups||[]).filter(g=>g.submitted);}
function notice(text){$('#notice').textContent=text;$('#notice').style.display='block';clearTimeout(notice.timer);notice.timer=setTimeout(()=>$('#notice').style.display='none',5000);}
function bind(selector,event,fn){document.querySelectorAll(selector).forEach(el=>el.addEventListener(event,fn));}
function photo(o){return `<img src="assets/${o.id}.jpg?v=4" alt=""><span>${esc(o.name)}</span>`;}
function roleCards(group,role,compact=false){const list=getDeck(state.room,Number(group.id)).filter(o=>group.board?.[o.id]===role);return list.length?list.map(o=>`<div class="display-organism ${compact?'compact':''}">${photo(o)}</div>`).join(''):'<p class="empty-role">분류한 생물 없음</p>';}
function overview(){return `<div class="display-heading"><div><p class="eyebrow">친구들의 생각을 함께 살펴봐요</p><h1>우리 반 생물 분류 결과</h1></div><strong class="submission-count">${readyGroups().length}<span> / 6모둠 제출</span></strong></div><div class="display-grid">${[1,2,3,4,5,6].map(i=>{const g=groupAt(i),ready=g?.submitted;return `<button class="group-result ${ready?'ready':'waiting'}" data-group="${i}" ${ready?'':'disabled'}><div class="group-title"><h2>${i}모둠</h2><span class="submission-tag">${ready?'제출 완료':'제출 기다리는 중'}</span></div>${ready?`<div class="overview-roles">${Object.entries(roles).map(([r,label])=>`<section class="role-${r}"><h3>${label}</h3><div class="overview-pictures">${roleCards(g,r,true)}</div></section>`).join('')}</div><p class="open-hint">눌러서 사진과 분류 이유 크게 보기 ↗</p>`:'<div class="waiting-content"><span aria-hidden="true">🌱</span><p>모둠에서 결과를 제출하면<br>여기에 나타나요.</p></div>'}</button>`;}).join('')}</div>`;}
function detail(){const g=groupAt(selected);if(!g?.submitted){selected=null;return overview();}const deck=getDeck(state.room,selected);return `<div class="display-heading"><div><p class="eyebrow">우리 모둠의 판단과 근거</p><h1>${selected}모둠의 탐구 발표</h1></div><div class="row"><button id="previous" aria-label="이전 제출 모둠">← 이전 모둠</button><button id="next" aria-label="다음 제출 모둠">다음 모둠 →</button></div></div><div class="presentation-roles">${Object.entries(roles).map(([r,label])=>`<section class="presentation-role role-${r}"><h2>${label}</h2><div class="presentation-pictures">${roleCards(g,r)}</div><div class="presentation-reason"><p class="sentence-lead">${esc(sentenceLead(r,g.board||{},deck))}</p><p class="reason-text">이유는 <strong>${esc(g.reasons?.[r]||'아직 이유를 적지 않았어요.')}</strong> 때문입니다.</p></div></section>`).join('')}</div>${!g.reasons&&g.reason?`<section class="legacy-reason"><h2>우리 모둠의 발표</h2><p>${esc(g.reason)}</p></section>`:''}`;}
function render(){root.innerHTML=`<nav class="display-toolbar" aria-label="발표 모둠 선택"><button id="overview" class="${selected===null?'primary':''}">6모둠 전체 보기</button><div class="group-tabs">${[1,2,3,4,5,6].map(i=>`<button data-group="${i}" class="${selected===i?'primary':''}" ${groupAt(i)?.submitted?'':'disabled'}>${i}모둠${groupAt(i)?.submitted?' ✓':''}</button>`).join('')}</div><label class="auto-option"><input id="auto-open" type="checkbox" ${autoOpen?'checked':''}>새 제출 자동 확대</label><button id="font-size" aria-pressed="${largeText}">${largeText?'기본 글씨':'글씨 더 크게'}</button><button id="refresh">새로고침</button></nav><div class="display-connection"><span id="connection" role="status">${esc(connection)}</span>${state.room.closed?'<span>종료된 수업 · 제출 결과 보기</span>':''}</div>${selected===null?overview():detail()}`;
root.classList.toggle('large-text',largeText);
bind('[data-group]','click',e=>{selected=Number(e.currentTarget.dataset.group);render();});
bind('#overview','click',()=>{selected=null;render();});
bind('#auto-open','change',e=>{autoOpen=e.currentTarget.checked;});
bind('#font-size','click',()=>{largeText=!largeText;render();});
bind('#refresh','click',()=>refresh());
bind('#previous','click',()=>move(-1));bind('#next','click',()=>move(1));
}
function move(direction){const ids=readyGroups().map(g=>Number(g.id)).sort((a,b)=>a-b);if(!ids.length)return;selected=ids[(ids.indexOf(selected)+direction+ids.length)%ids.length];render();}
function setConnection(text){connection=text;const el=$('#connection');if(el)el.textContent=text;}
async function request(action,data={}){const res=await fetch('/api/classroom',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action,room,...data})});let body;try{body=await res.json();}catch{throw Error('서버 응답을 확인해 주세요.');}if(!res.ok){if(res.status===401){authenticated=false;login();}const error=Error(body.error||'결과를 불러오지 못했어요.');error.status=res.status;throw error;}return body;}
function accept(next){const first=state===null, changed=JSON.stringify(next)!==previousJSON;const incoming=next.groups.filter(g=>g.submitted&&signatures.get(g.id)!==signature(g));state=next;previousJSON=JSON.stringify(next);signatures=new Map(next.groups.filter(g=>g.submitted).map(g=>[g.id,signature(g)]));if(!first&&incoming.length){incoming.sort((a,b)=>(a.submittedAt||0)-(b.submittedAt||0)||Number(a.id)-Number(b.id));const newest=incoming.at(-1);if(autoOpen)selected=Number(newest.id);notice(incoming.map(g=>g.id+'모둠').join(', ')+'의 결과가 도착했어요!');}if(selected!==null&&!groupAt(selected)?.submitted)selected=null;connection='● 자동 갱신 중 · '+new Date().toLocaleTimeString('ko-KR');if(changed||first)render();else setConnection(connection);}
async function refresh(){if(loading||!room)return;loading=true;try{const next=await request('display');authenticated=true;accept(next);}catch(e){setConnection('연결 확인 필요 · 기존 결과를 표시하고 있어요');if(!state&&e.status!==401){root.innerHTML='<section class="panel narrow"><h1>연결을 확인해 주세요</h1><p>모둠 결과를 아직 불러오지 못했어요. 잠시 후 자동으로 다시 확인합니다.</p><button id="retry-display" class="primary">다시 연결</button></section>';bind('#retry-display','click',()=>refresh());}if(authenticated||!state)notice(e.message);}finally{loading=false;}}
function login(){previousJSON='';root.innerHTML=`<section class="panel narrow"><h1>전자칠판 열기</h1><p>교사 비밀번호로 로그인하면 제출된 모둠 결과를 볼 수 있습니다.</p><form id="display-login"><label>교사 비밀번호<input id="password" type="password" autocomplete="current-password" required></label><button class="primary" type="submit">전자칠판 시작</button><p id="login-error" class="error" role="alert"></p></form></section>`;bind('#display-login','submit',async e=>{e.preventDefault();const password=$('#password').value;try{await request('login',{password});await refresh();}catch(error){const el=$('#login-error');if(el)el.textContent=error.message;}});}
$('#full').addEventListener('click',async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen();}catch{notice('브라우저의 전체 화면 버튼 또는 F11을 눌러 주세요.');}});
if(room)refresh();else root.innerHTML='<section class="panel narrow"><h1>전자칠판 수업을 선택해 주세요</h1><p>교사 수업관리에서 수업을 연 뒤 <b>전자칠판 열기</b>를 눌러 주세요.</p><a href="teacher.html"><button class="primary">교사 수업관리</button></a></section>';
setInterval(()=>{if(room&&!$('#display-login')&&!document.hidden)refresh();},2500);
window.addEventListener('online',()=>{if(room&&!$('#display-login'))refresh();});
